IF NOT EXISTS (SELECT * FROM sys.databases WHERE name = 'PetCare')
BEGIN
    CREATE DATABASE PetCare COLLATE Vietnamese_CI_AS;
END
GO

USE PetCare;
GO

-- Drop redundant tables and clean up foreign keys
EXEC sp_MSforeachtable 'ALTER TABLE ? NOCHECK CONSTRAINT ALL';
GO

DECLARE @sql NVARCHAR(MAX) = N'';
SELECT @sql += N'DROP TABLE IF EXISTS dbo.[' + name + N'];' 
FROM sys.tables WHERE is_ms_shipped = 0;
EXEC sp_executesql @sql;
GO

CREATE TABLE dbo.[roles] (
    [id] NVARCHAR(50) NOT NULL,
    [name] NVARCHAR(255) NOT NULL,
    [description] NVARCHAR(255) NULL,
    CONSTRAINT [PK_roles] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[users] (
    [id] NVARCHAR(50) NOT NULL,
    [email] NVARCHAR(255) NOT NULL,
    [hashed_password] NVARCHAR(255) NOT NULL,
    [full_name] NVARCHAR(255) NULL,
    [is_active] BIT NULL,
    [created_at] DATETIME2 NULL,
    [updated_at] DATETIME2 NULL,
    CONSTRAINT [PK_users] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[user_roles] (
    [user_id] NVARCHAR(50) NOT NULL,
    [role_id] NVARCHAR(50) NOT NULL,
    CONSTRAINT [PK_user_roles] PRIMARY KEY ([user_id], [role_id])
);
GO

CREATE TABLE dbo.[pets] (
    [id] NVARCHAR(50) NOT NULL,
    [name] NVARCHAR(255) NOT NULL,
    [avatar] NVARCHAR(255) NULL,
    [species] NVARCHAR(5) NOT NULL,
    [breed] NVARCHAR(255) NULL,
    [date_of_birth] DATE NULL,
    [sex] NVARCHAR(7) NULL,
    [neutered] BIT NULL,
    [microchip] NVARCHAR(255) NULL,
    [color] NVARCHAR(255) NULL,
    [distinguishing_marks] NVARCHAR(MAX) NULL,
    [lost_mode] BIT NULL,
    [created_at] DATETIME2 NULL,
    [updated_at] DATETIME2 NULL,
    CONSTRAINT [PK_pets] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[qr_codes] (
    [id] NVARCHAR(50) NOT NULL,
    [pet_id] NVARCHAR(50) NOT NULL,
    [token] NVARCHAR(255) NOT NULL,
    [is_active] BIT NULL,
    [created_at] DATETIME2 NULL,
    CONSTRAINT [PK_qr_codes] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[services] (
    [id] NVARCHAR(50) NOT NULL,
    [name] NVARCHAR(255) NOT NULL,
    [description] NVARCHAR(MAX) NULL,
    [category] NVARCHAR(10) NOT NULL,
    [base_price] FLOAT NOT NULL,
    [estimated_duration_minutes] INT NOT NULL,
    [is_active] BIT NULL,
    CONSTRAINT [PK_services] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[appointments] (
    [id] NVARCHAR(50) NOT NULL,
    [customer_id] NVARCHAR(50) NOT NULL,
    [pet_id] NVARCHAR(50) NOT NULL,
    [caregiver_id] NVARCHAR(50) NULL,
    [scheduled_time] DATETIME2 NOT NULL,
    [status] NVARCHAR(11) NULL,
    [total_price] FLOAT NULL,
    [notes] NVARCHAR(MAX) NULL,
    [created_at] DATETIME2 NULL,
    [updated_at] DATETIME2 NULL,
    CONSTRAINT [PK_appointments] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[medical_records] (
    [id] NVARCHAR(50) NOT NULL,
    [pet_id] NVARCHAR(50) NOT NULL,
    [visit_date] DATE NOT NULL,
    [clinic] NVARCHAR(255) NULL,
    [veterinarian] NVARCHAR(255) NULL,
    [diagnosis] NVARCHAR(MAX) NULL,
    [treatment] NVARCHAR(MAX) NULL,
    [document_url] NVARCHAR(255) NULL,
    [created_at] DATETIME2 NULL,
    CONSTRAINT [PK_medical_records] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[care_sessions] (
    [id] NVARCHAR(50) NOT NULL,
    [appointment_id] NVARCHAR(50) NOT NULL,
    [caregiver_id] NVARCHAR(50) NOT NULL,
    [status] NVARCHAR(9) NULL,
    [started_at] DATETIME2 NULL,
    [ended_at] DATETIME2 NULL,
    [created_at] DATETIME2 NULL,
    CONSTRAINT [PK_care_sessions] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[products] (
    [id] NVARCHAR(50) NOT NULL,
    [sku] NVARCHAR(50) NOT NULL,
    [name] NVARCHAR(255) NOT NULL,
    [slug] NVARCHAR(255) NOT NULL,
    [category] NVARCHAR(50) NOT NULL,
    [target_pet] NVARCHAR(20) NOT NULL,
    [brand] NVARCHAR(100) NOT NULL,
    [price] FLOAT NOT NULL,
    [original_price] FLOAT NULL,
    [discount_percent] INT NULL,
    [unit] NVARCHAR(50) NOT NULL,
    [stock_quantity] INT NOT NULL,
    [rating] FLOAT NULL,
    [review_count] INT NULL,
    [image_url] NVARCHAR(1000) NULL,
    [badge] NVARCHAR(50) NULL,
    [description] NVARCHAR(MAX) NOT NULL,
    [ingredients] NVARCHAR(MAX) NULL,
    [usage_instructions] NVARCHAR(MAX) NULL,
    [is_active] BIT NULL,
    [is_featured] BIT NULL,
    [created_at] DATETIME2 NULL,
    [updated_at] DATETIME2 NULL,
    CONSTRAINT [PK_products] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[payments] (
    [id] NVARCHAR(50) NOT NULL,
    [appointment_id] NVARCHAR(50) NOT NULL,
    [amount] FLOAT NOT NULL,
    [status] NVARCHAR(9) NULL,
    [payment_method] NVARCHAR(13) NULL,
    [transaction_id] NVARCHAR(255) NULL,
    [notes] NVARCHAR(MAX) NULL,
    [created_at] DATETIME2 NULL,
    [updated_at] DATETIME2 NULL,
    CONSTRAINT [PK_payments] PRIMARY KEY ([id])
);
GO

CREATE TABLE dbo.[notifications] (
    [id] NVARCHAR(50) NOT NULL,
    [user_id] NVARCHAR(50) NOT NULL,
    [type] NVARCHAR(12) NULL,
    [title] NVARCHAR(255) NOT NULL,
    [message] NVARCHAR(MAX) NOT NULL,
    [is_read] BIT NULL,
    [action_url] NVARCHAR(255) NULL,
    [metadata_json] NVARCHAR(MAX) NULL,
    [created_at] DATETIME2 NULL,
    CONSTRAINT [PK_notifications] PRIMARY KEY ([id])
);
GO

