-- Core Table: products (28 rows)
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'ea885bad-1dd3-4a06-bdc2-504a86700fa4', N'PET-DOG-GLD-01', N'Chó Golden Retriever Thuần Chủng 2.5 Tháng Tuổi', N'cho-golden-retriever-thuan-chung-2-5-thang', N'PET', N'DOG', N'Trại Nhân Giống PetCare VKA', 8500000.0, 9500000.0, 11, N'Bé (Đực - 2.5 tháng)', 2, 5.0, 38, N'https://images.unsplash.com/photo-1552053831-71594a27632d?w=800&q=80', N'THUẦN CHỦNG VKA', N'Bé Golden Retriever lông vàng ánh kim dày mượt, khung xương to tròn, mặt cân đối, mắt to thông minh, đã biết ăn hạt ngâm. Tính cách vô cùng hiền hòa, quấn chủ và thân thiện với trẻ nhỏ.', N'Giống: Golden Retriever thuần chủng. Tuổi: 2.5 tháng. Giới tính: Đực. Tẩy giun: 2 lần. Tiêm phòng: Đã tiêm 2 mũi vaccine 7 bệnh Pfizer. Đã cấy vi mạch Microchip định danh.', N'Bảo hành 30 ngày đối với 2 bệnh Care và Parvo. Tặng kèm hợp đồng mua bán, sổ tiêm chủng thú y và gói dinh dưỡng Royal Canin Puppy 4kg khi đón bé.', 1, 1, '2026-10-11T16:27:00.514797+00:00', '2026-10-11T16:27:00.514801+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'9783466c-7a28-4b64-8dfa-d39adb7e27cd', N'PET-DOG-CRG-02', N'Chó Corgi Pembroke Chân Ngắn Tri-Color Siêu Đáng Yêu', N'cho-corgi-pembroke-chan-ngan-tri-color', N'PET', N'DOG', N'Trại Nhân Giống PetCare VKA', 9200000.0, 10500000.0, 12, N'Bé (Cái - 3 tháng)', 1, 5.0, 42, N'https://images.unsplash.com/photo-1517423440428-a5a00ad493e8?w=800&q=80', N'BẢO HÀNH 30 NGÀY', N'Bé Corgi mông trái tim bồng bềnh, 4 chân ngắn cực kỳ đáng yêu, bờ ngực nở nang, tai vểnh chuẩn form. Đã cai sữa mẹ hoàn toàn và ăn hạt khô tốt.', N'Giống: Pembroke Welsh Corgi. Màu lông: Vàng trắng (Fawn & White). Tuổi: 3 tháng. Giới tính: Cái. Đã tiêm đủ 2 mũi vaccine Care-Parvo, tẩy giun định kỳ.', N'Bảo hành thuần chủng trọn đời. Hỗ trợ khám sức khỏe miễn phí 1 năm tại Hệ thống Thú y PetCare AI.', 1, 1, '2026-10-11T16:27:00.514807+00:00', '2026-10-11T16:27:00.514808+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'10c650a7-1b53-4065-b5b1-9db7913a6617', N'PET-DOG-PDL-03', N'Chó Poodle Tiny Nâu Đỏ Lông Xoăn Tít Không Rụng Lông', N'cho-poodle-tiny-nau-do-long-xoan', N'PET', N'DOG', N'Trại Nhân Giống PetCare VKA', 4800000.0, 5500000.0, 13, N'Bé (Đực - 2 tháng)', 3, 4.9, 56, N'https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800&q=80', N'DỄ NUÔI', N'Dòng Poodle Tiny nhỏ gọn không rụng lông, lông xoăn tít màu đỏ nâu óng ả, thông minh lanh lợi hàng đầu các loài chó cảnh, rất thích hợp nuôi trong căn hộ.', N'Giống: Tiny Poodle. Cân nặng hiện tại: 1.1kg (trưởng thành tối đa 3kg). Đã tiêm 1 mũi vaccine Vanguard 7 bệnh, ăn hạt ngâm và pate khỏe mạnh.', N'Tặng kèm balo phi hành gia, bình nước gắn chuồng và 1 khóa tư vấn huấn luyện chó cơ bản.', 1, 1, '2026-10-11T16:27:00.514811+00:00', '2026-10-11T16:27:00.514812+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'97e0144e-84cf-4874-b8ca-074a640a5656', N'PET-CAT-BSH-04', N'Mèo Anh Lông Ngắn (British Shorthair) Xám Xanh Má Phính', N'meo-anh-long-ngan-british-shorthair-blue', N'PET', N'CAT', N'PetCare Cattery WCF', 6500000.0, 7200000.0, 10, N'Bé (Đực - 2.5 tháng)', 2, 5.0, 64, N'https://images.unsplash.com/photo-1513360371669-4adf3dd7dff8?w=800&q=80', N'MẶT PHÍNH MẬP MẠP', N'Bé Mèo Anh Lông Ngắn màu xám xanh thuần chủng, khung xương to tròn, má bánh bao phính núng nính, mắt hổ phách to tròn long lanh, lông dày mượt như nhung.', N'Giống: British Shorthair (BSH). Màu: Blue (Xám xanh cổ điển). Tuổi: 2.5 tháng. Đã biết đi vệ sinh thau cát thành thạo, ăn hạt Orijen và súp Ciao Churu.', N'Tặng kèm sổ tiêm chủng thú y 2 mũi phòng 4 bệnh mèo, xẻng xúc cát và túi hạt 1.8kg.', 1, 1, '2026-10-11T16:27:00.514814+00:00', '2026-10-11T16:27:00.514815+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'72d4b9ae-71b9-4ec4-b581-8f87518f1351', N'PET-CAT-RGD-05', N'Mèo Ragdoll Thuần Chủng Mắt Xanh Biển Bicolor Quý Tộc', N'meo-ragdoll-thuan-chung-mat-xanh-bicolor', N'PET', N'CAT', N'PetCare Cattery WCF', 12500000.0, 14000000.0, 11, N'Bé (Cái - 3 tháng)', 1, 5.0, 28, N'https://images.unsplash.com/photo-1574158622682-e40e69881006?w=800&q=80', N'QUÝ TỘC CÔNG CHÚA', N'Nàng ''công chúa'' mèo Ragdoll với đôi mắt xanh ngọc bích mê hoặc lòng người, bộ lông tuyết dài bồng bềnh và tính cách siêu dịu dàng, thích được ôm ấp bế bồng cả ngày.', N'Giống: Ragdoll thuần chủng. Hoa văn: Seal Point Bicolor. Phả hệ WCF bố mẹ nhập Nga. Đã tiêm đủ 2 mũi vaccine Merial, xét nghiệm âm tính FPV & FeLV.', N'Bảo hành gen thuần chủng trọn đời. Hợp đồng mua bán minh bạch và giao tận nhà bằng xe chuyên dụng.', 1, 1, '2026-10-11T16:27:00.514818+00:00', '2026-10-11T16:27:00.514818+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'1d235106-a10f-49ed-9fcc-a90ae4f2adeb', N'PET-CAT-SCT-06', N'Mèo Tai Cụp Scottish Fold Màu Bicolor Trắng Xám Siêu Xinh', N'meo-tai-cup-scottish-fold-bicolor', N'PET', N'CAT', N'PetCare Cattery WCF', 7800000.0, 8800000.0, 11, N'Bé (Đực - 2.5 tháng)', 2, 4.9, 35, N'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800&q=80', N'TAI CỤP SÁT', N'Đôi tai cụp sát đầu độc đáo, khuôn mặt tròn xoe như quả bóng, đôi mắt to ngơ ngác cực kỳ đáng yêu, tính tình trầm tĩnh thích quấn chân người.', N'Giống: Scottish Fold tai cụp. Độ tuổi: 2.5 tháng. Đã xổ giun 2 đợt, tiêm 1 mũi vaccine phòng 4 bệnh mèo.', N'Bảo hành sức khỏe 30 ngày. Hướng dẫn chăm sóc và tư vấn dinh dưỡng trọn đời bởi Bác sĩ Thú y PetCare.', 1, 1, '2026-10-11T16:27:00.514820+00:00', '2026-10-11T16:27:00.514820+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'27e595b6-2f8d-47aa-801d-50cd18092bd4', N'PET-DOG-POM-07', N'Chó Phốc Sóc Pomeranian Trắng Tuyết Mặt Gấu Mini', N'cho-phoc-soc-pomeranian-trang-tuyet-mat-gau', N'PET', N'DOG', N'Trại Nhân Giống PetCare VKA', 7200000.0, 8200000.0, 12, N'Bé (Cái - 2 tháng)', 2, 5.0, 47, N'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800&q=80', N'MẶT GẤU TRẮNG TINH', N'Bé Phốc Sóc Pomeranian mini lông trắng tinh khôi dày xù 2 lớp, mặt ngắn tròn như chú gấu bông nhỏ, nhanh nhẹn quấn quýt chủ nhân mọi lúc mọi nơi.', N'Giống: Pomeranian Teacup/Mini. Cân nặng: 700g. Mõm ngắn, chân lùn, mắt đen láy. Đã tiêm 2 mũi vaccine phòng 7 bệnh.', N'Bảo hành sức khỏe 30 ngày. Tặng kèm chuồng tĩnh điện và bộ đồ chơi gặm KONG.', 1, 1, '2026-10-11T16:27:00.514822+00:00', '2026-10-11T16:27:00.514822+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'a7292ca7-6920-4bc2-b648-8cd733032906', N'FOOD-RC-DOG-01', N'Hạt Royal Canin Medium Adult Cho Chó Trưởng Thành', N'royal-canin-medium-adult-dog', N'FOOD', N'DOG', N'Royal Canin', 385000.0, 450000.0, 14, N'Túi 4kg', 45, 4.9, 218, N'https://upload.wikimedia.org/wikipedia/commons/8/85/Royal_Canin_cat_food.jpg', N'BÁN CHẠY', N'Thức ăn khô dinh dưỡng cao cấp của thương hiệu Royal Canin danh tiếng từ Pháp. Cân bằng đặc chế cho chó kích cỡ trung bình (11 - 25kg) từ 12 tháng tuổi trở lên. Tăng cường hệ miễn dịch tự nhiên, duy trì trọng lượng lý tưởng và hệ tiêu hóa khỏe mạnh.', N'Thịt gia cầm sấy khô, bắp, bột bắp, bột mì, mỡ động vật, đạm động vật thủy phân, củ cải đường, dầu cá, dầu đậu nành, men bia, khoáng chất (Kẽm, Sắt, Mangan, Selen), Vitamin A, D3, E.', N'Chó 11-15kg: 180-220g/ngày. Chó 16-20kg: 230-270g/ngày. Chó 21-25kg: 280-320g/ngày. Chia làm 2 bữa/ngày. Luôn chuẩn bị sẵn nước uống sạch.', 1, 1, '2026-10-11T16:27:00.514824+00:00', '2026-10-11T16:27:00.514825+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'6cc867e0-b5f8-4183-bac9-50611f183729', N'FOOD-RC-CAT-02', N'Hạt Royal Canin Gastrointestinal Hairball Tiêu Hóa Cho Mèo', N'royal-canin-hairball-cat-food', N'FOOD', N'CAT', N'Royal Canin', 320000.0, 360000.0, 11, N'Túi 2kg', 35, 5.0, 185, N'https://upload.wikimedia.org/wikipedia/commons/3/39/Gastrointestinal_Haiball_cat_dry_food_%28Royal_Canin%29.jpg', N'CHUẨN THÚ Y', N'Dòng hạt thú y chuyên biệt của Royal Canin giúp loại bỏ búi lông tự nhiên qua đường tiêu hóa, chống nôn trớ và bảo vệ đường ruột mèo cưng tối ưu.', N'Protein gia cầm cô lập L.I.P, chất xơ mã đề Psyllium, mỡ gà, dầu cá giàu Omega-3, men FOS và khoáng vi lượng.', N'Mèo 3-4kg: 45-55g/ngày. Mèo 5-6kg: 65-80g/ngày. Cho ăn liên tục 14-21 ngày để thấy rõ hiệu quả giảm búi lông.', 1, 1, '2026-10-11T16:27:00.514826+00:00', '2026-10-11T16:27:00.514827+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'4068cac7-c444-411f-8660-e1ec9d565a6c', N'FOOD-WSK-CAT-03', N'Hạt Whiskas Vị Gà & Đậu Nành Dinh Dưỡng Toàn Diện Cho Mèo', N'whiskas-chicken-dry-cat-food', N'FOOD', N'CAT', N'Whiskas', 145000.0, 165000.0, 12, N'Túi 1.2kg', 75, 4.8, 320, N'https://upload.wikimedia.org/wikipedia/commons/1/16/Whiskas_cat%27s_petfood_with_chicken_dry.jpg', N'BÁN CHẠY', N'Thức ăn hạt Whiskas hương vị thịt gà thơm lừng, viên nhân túi giòn tan bổ sung Taurine sáng mắt và Vitamin A cho lông bóng mượt.', N'Ngũ cốc nguyên cám, thịt gà sấy, bột đậu nành, mỡ động vật, dầu đậu nành, Taurine, Vitamin E và kẽm sinh học.', N'Mèo 2-3kg: 40-50g/ngày. Mèo 4-5kg: 60-75g/ngày. Luôn có sẵn nước uống sạch.', 1, 1, '2026-10-11T16:27:00.514828+00:00', '2026-10-11T16:27:00.514829+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'58d7bc94-e36d-4254-ba08-4a90dfe7c486', N'FOOD-ORJ-CAT-04', N'Hạt Orijen Cat & Kitten 85% Đạm Gia Cầm & Cá Đánh Bắt Tự Nhiên', N'orijen-cat-kitten-premium', N'FOOD', N'CAT', N'Orijen', 620000.0, 690000.0, 10, N'Túi 1.8kg', 28, 5.0, 142, N'https://upload.wikimedia.org/wikipedia/commons/2/26/Dry_cat_food_01.jpg', N'SIÊU CAO CẤP', N'Dòng hạt không ngũ cốc (Grain-Free) số 1 thế giới từ Canada. 85% thịt tươi, cung cấp protein sinh học dồi dào, phát triển cơ bắp và bảo vệ đường tiết niệu của mèo.', N'Thịt gà tươi rút xương (18%), gà tây tươi (7%), trứng tươi (5%), gan gà tươi (5%), cá bơn tươi (4%), cá trích (4%), đỗ xanh, đậu lăng.', N'Mèo con: 60-90g/ngày. Mèo trưởng thành 3-4kg: 45-60g/ngày. Mèo 5-6kg: 75-90g/ngày.', 1, 1, '2026-10-11T16:27:00.514830+00:00', '2026-10-11T16:27:00.514830+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'565a505e-93f6-46f6-8935-c300d670b112', N'FOOD-MEO-CAT-05', N'Hạt Me-O Vị Cá Ngừ Cho Mèo Trưởng Thành (Adult Tuna)', N'meo-tuna-adult-cat-food', N'FOOD', N'CAT', N'Me-O', 115000.0, 130000.0, 11, N'Túi 1.2kg', 90, 4.7, 290, N'https://upload.wikimedia.org/wikipedia/commons/0/0e/Dry_cat_food_04.jpg', N'PHỔ BIẾN NHẤT', N'Thương hiệu hạt thức ăn cho mèo quen thuộc hàng đầu tại Việt Nam. Giàu Taurine, Vitamin C và Canxi giúp xương răng chắc khỏe, giảm nguy cơ sỏi bàng quang.', N'Bột cá ngừ, ngũ cốc nguyên hạt, mỡ gia cầm, bột củ cải đường, Taurine, Vitamin C, Vitamin D3, Canxi photphat.', N'Mèo 2-3kg: 45-60g/ngày. Mèo 3-4kg: 65-80g/ngày.', 1, 0, '2026-10-11T16:27:00.514832+00:00', '2026-10-11T16:27:00.514833+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'28652fed-88ec-47c6-b405-446b2d7eabed', N'FOOD-SMH-DOG-06', N'Hạt SmartHeart Gold Puppy Cho Chó Con Vị Bò & Sữa', N'smartheart-gold-puppy-beef', N'FOOD', N'DOG', N'SmartHeart', 165000.0, 195000.0, 15, N'Túi 1.5kg', 55, 4.7, 89, N'https://upload.wikimedia.org/wikipedia/commons/4/4f/Dog_Food_%28208810939%29.jpg', N'TIẾT KIỆM', N'Bổ sung DHA từ dầu cá biển và Choline giúp phát triển trí não thông minh. Tỷ lệ Canxi và Phốt pho cân đối giúp cún con phát triển khung xương vững chắc.', N'Thịt bò tươi sấy, bột sữa nguyên kem, mỡ cừu, dầu cá hồi, men vi sinh Prebiotics MOS, Omega 3 & 6, Vitamin tổng hợp.', N'Cho ăn 3-4 bữa/ngày cho cún dưới 6 tháng tuổi. Ngâm nước ấm 5 phút nếu cún mới tập ăn hạt.', 1, 0, '2026-10-11T16:27:00.514834+00:00', '2026-10-11T16:27:00.514835+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'309cab98-c4e0-4545-9d82-b1e482245fe2', N'FOOD-PUR-DOG-07', N'Hạt Purina Pro Plan Sensitive Skin & Stomach Thịt Cá Hồi', N'purina-pro-plan-salmon-sensitive', N'FOOD', N'DOG', N'Purina', 420000.0, 480000.0, 12, N'Túi 2.5kg', 38, 4.9, 92, N'https://upload.wikimedia.org/wikipedia/commons/7/71/Dog_food_in_a_bowl.jpg', N'CHUYÊN BIỆT', N'Dành riêng cho chó có cơ địa dị ứng, ngứa da hoặc phân lỏng. Công thức thịt cá hồi tươi làm nguyên liệu chính không chứa bắp, lúa mì hay đậu nành.', N'Cá hồi tươi (26%), bột gạo tấm, mỡ bò, bột cá trích, dầu hạt cải, yến mạch, men vi sinh sống Probiotics.', N'Cún 5-10kg: 100-160g/ngày. Cún 11-20kg: 170-270g/ngày.', 1, 1, '2026-10-11T16:27:00.514836+00:00', '2026-10-11T16:27:00.514837+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'e409cb34-65c3-4964-8c8d-6ed958ef5da9', N'PATE-WSK-CAT-08', N'Pate Lon Cho Mèo Canned Cat Food Vị Cá Biển Sốt Gravy', N'canned-cat-food-ocean-fish', N'PATE', N'CAT', N'Whiskas', 38000.0, 45000.0, 15, N'Lon 400g', 110, 4.8, 210, N'https://upload.wikimedia.org/wikipedia/commons/d/d0/Canned_Cat_Food1.jpg', N'COMBO HOT', N'Lon pate thịt cá tươi ngon hảo hạng sốt gravy sánh mịn. Cung cấp độ ẩm dồi dào lên đến 82% giúp mèo cưng tránh sỏi thận và kích thích ăn ngon miệng.', N'Cá ngừ, cá thu, nước dùng hải sản dashi, bột thạch, Taurine, Vitamin E, khoáng chất vi lượng.', N'Mèo 2-4kg: 1/2 lon/ngày chia 2 lần ăn. Đậy kín bảo quản tủ lạnh sau khi mở nắp.', 1, 1, '2026-10-11T16:27:00.514838+00:00', '2026-10-11T16:27:00.514839+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'85945c9b-068b-4066-be5c-bb5d843f2dba', N'PATE-RC-REC-09', N'Pate Dinh Dưỡng Hồi Sức Lâm Sàng Royal Canin Recovery Cho Chó Mèo', N'royal-canin-recovery-can', N'PATE', N'ALL', N'Royal Canin', 95000.0, 115000.0, 17, N'Lon 195g', 40, 5.0, 88, N'https://upload.wikimedia.org/wikipedia/commons/d/d0/Canned_Cat_Food1.jpg', N'Y KHOA', N'Dòng thức ăn đặc trị năng lượng cao dành cho chó mèo ốm yếu, chán ăn, hậu phẫu hoặc cần phục hồi thể trạng nhanh chóng. Kết cấu siêu mịn có thể bơm qua xi-lanh.', N'Gan gà, thịt gia cầm, sữa đặc biệt không lactose, dầu cá tinh khiết, Axit amin thiết yếu, Phức hợp chống oxy hóa tăng cường.', N'Dùng theo chỉ định của bác sĩ thú y hoặc liều khuyến nghị: 1 lon/ngày cho thú cưng 4-5kg.', 1, 1, '2026-10-11T16:27:00.514840+00:00', '2026-10-11T16:27:00.514840+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'f0621b62-7a3f-4b6b-83c7-955b64104774', N'SNC-INB-CAT-10', N'Súp Thưởng Tuýp Dạng Kem Cho Mèo Inaba Ciao Churu Gà & Cá', N'ciao-churu-tube-treat-cat', N'SNACK', N'CAT', N'Inaba Ciao', 42000.0, 50000.0, 16, N'Túi 4 thanh (14g x 4)', 140, 4.9, 420, N'https://upload.wikimedia.org/wikipedia/commons/d/d5/Cat_offered_a_tube_treat_during_handling_in_Newark%2C_New_Jersey.jpg', N'SIÊU ƯA CHUỘNG', N'Thanh kem súp thưởng tuýp số 1 Nhật Bản, 100% từ phi lê thịt tươi ngọt ngào. Bổ sung chiết xuất trà xanh giảm mùi hôi phân và Collagen làm mượt lông mèo.', N'Ức gà tươi, cá ngừ đại dương, nước dùng dashi, Vitamin E, Taurine, chiết xuất trà xanh hữu cơ.', N'Xé đầu tuýp và bóp cho mèo liếm trực tiếp hoặc trộn vào hạt khô. Cho ăn 2-3 tuýp/ngày.', 1, 1, '2026-10-11T16:27:00.514842+00:00', '2026-10-11T16:27:00.514842+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'72386915-b440-45e4-a3f9-8810dda3660a', N'SNC-BW-DOG-11', N'Bánh Thưởng Khúc Xương Gặm Sạch Răng Dog Biscuits Dinh Dưỡng', N'dog-biscuit-bone-treat', N'SNACK', N'DOG', N'Bow Wow', 55000.0, 70000.0, 21, N'Hộp 200g (12 khúc)', 85, 4.8, 130, N'https://upload.wikimedia.org/wikipedia/commons/1/17/A_Dog_biscuit.jpg', N'SẠCH RĂNG', N'Bánh quy dinh dưỡng nướng giòn hình khúc xương kinh điển giúp cún ma sát mảng bám men răng, khử hôi miệng và bổ sung Canxi giúp xương khớp rắn rỏi.', N'Bột mì nguyên cám, thịt gà nạc sấy, men vi sinh, Canxi cacbonat thực phẩm, Vitamin E, diệp lục tố khử mùi.', N'Cho cún cưng nhai thưởng 2-3 chiếc mỗi ngày khi huấn luyện vâng lời hoặc sau bữa chính.', 1, 0, '2026-10-11T16:27:00.514844+00:00', '2026-10-11T16:27:00.514844+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'd5599533-ca44-419f-ac61-eb65da316868', N'SNC-RAW-DOG-12', N'Xương Da Bò Rawhide Chew Bone Tự Nhiên Chống Cắn Phá', N'rawhide-chew-bone-dog', N'SNACK', N'DOG', N'Orgo Bone', 48000.0, 60000.0, 20, N'Thanh dài 15cm', 90, 4.8, 115, N'https://upload.wikimedia.org/wikipedia/commons/4/44/Dog_with_rawhide_chew_toy.jpg', N'BỀN BỈ', N'Xương gặm từ da bò tự nhiên 100% sấy khô không tẩm hóa chất. Cực kỳ dẻo dai giúp chó thỏa mãn bản năng gặm cắn hàng giờ mà không cắn phá bàn ghế.', N'100% Da bò nguyên tấm tự nhiên ép nhiệt, không chất bảo quản.', N'Để cún tự do gặm nhai. Thay thế khi thanh xương đã bị cắn quá ngắn tránh nuốt chửng.', 1, 0, '2026-10-11T16:27:00.514846+00:00', '2026-10-11T16:27:00.514846+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'fe79058a-a8d2-4cbc-bfc4-7e25d416509b', N'TOY-KONG-DOG-13', N'Đồ Chơi Cao Su Gặm KONG Classic Đỏ Nhồi Thức Ăn Chống Cắn Phá', N'kong-classic-red-rubber-toy', N'TOY', N'DOG', N'KONG', 265000.0, 310000.0, 15, N'Size M (Dành cho cún 7-16kg)', 30, 5.0, 288, N'https://upload.wikimedia.org/wikipedia/commons/e/e7/Dog_with_red_kong.jpg', N'CHÍNH HÃNG KONG', N'Mẫu đồ chơi gặm số 1 thế giới đến từ thương hiệu KONG (Mỹ). Làm bằng cao su thiên nhiên siêu đàn hồi nảy bất định. Lòng rỗng để nhét pate, bơ đậu phộng hoặc hạt khô giúp cún giải tỏa căng thẳng và tránh sủa bậy.', N'100% Cao su thiên nhiên siêu bền đàn hồi chuẩn FDA an toàn thực phẩm.', N'Nhồi pate hoặc hạt vào ruột KONG rồi để vào ngăn đông 2 giờ để tăng độ thử thách cho cún.', 1, 1, '2026-10-11T16:27:00.514848+00:00', '2026-10-11T16:27:00.514848+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'3dbedbc8-f4d5-4577-971b-294cf24fe091', N'TOY-WND-CAT-14', N'Cần Câu Mèo Lông Vũ Chuông Kèm Đồ Chơi Vờn Bắt Linh Hoạt', N'feather-wand-cat-toy-bell', N'TOY', N'CAT', N'PetCare Joy', 45000.0, 60000.0, 25, N'Bộ dây cần (Dài 90cm)', 120, 4.8, 240, N'https://upload.wikimedia.org/wikipedia/commons/9/9f/Carstian_Luyckx_-_A_kitten_crouched_on_the_left%2C_playing_with_a_feather_toy%2C_grapes%2C_and_peaches.jpg', N'GIẢM 25%', N'Cần câu sợi carbon siêu dẻo kết hợp chùm lông vũ tự nhiên và chuông leng keng kích thích bản năng săn mồi của mèo, giúp mèo vận động dẻo dai chống béo phì.', N'Cần sợi carbon đàn hồi, lông vũ gà sao tự nhiên đã khử trùng, chuông đồng ngân vang.', N'Vẫy nhẹ cần câu để mèo bật nhảy nhào lộn 15 phút mỗi ngày trước giờ ăn.', 1, 0, '2026-10-11T16:27:00.514850+00:00', '2026-10-11T16:27:00.514850+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'5688bfd2-fb7b-4a9b-b457-f8ef2c9565d1', N'SUP-CT-CAT-15', N'Nhà Cây Cào Móng Cat Tree Power Tower Đa Tầng Cho Mèo', N'cat-tree-power-tower-multi-tier', N'SUPPLY', N'CAT', N'PetCare Home', 580000.0, 720000.0, 19, N'Bộ lắp ráp (Cao 130cm)', 18, 4.9, 94, N'https://upload.wikimedia.org/wikipedia/commons/f/fd/Cats_Playing_on_Cat_Power_Tower_%288030352554%29.jpg', N'BÁN CHẠY', N'Tháp leo trèo cào móng vững chắc cho mèo thỏa thích leo trèo, cào móng và ngủ trên tầng cao. Quấn dây thừng sợi đay Sisal tự nhiên 100% không xơ vụn.', N'Khung gỗ ép thân thiện môi trường CARB-P2, dây đay Sisal tự nhiên, vải nỉ nhung cao cấp.', N'Lắp ráp theo sơ đồ kèm ốc vít trong 15 phút. Đặt sát tường góc thoáng mát.', 1, 1, '2026-10-11T16:27:00.514852+00:00', '2026-10-11T16:27:00.514852+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'98275c0c-74e0-412f-bc13-a35dbcd16294', N'SUP-BOWL-DOG-16', N'Bát Ăn Chống Sặc Chống Nuốt Vội Labyrinth Slow Feeder', N'dark-gray-slow-feeder-dog-bowl', N'SUPPLY', N'DOG', N'PetCare Home', 125000.0, 150000.0, 17, N'Chiếc (Đường kính 21cm)', 50, 4.9, 105, N'https://upload.wikimedia.org/wikipedia/commons/4/4c/Dark_Gray_Slow_Feeder_Dog_Bowl_with_Labyrinth_Pattern.jpg', N'KHUYÊN DÙNG', N'Bát ăn cấu trúc mê cung thông minh kéo dài thời gian ăn gấp 5-10 lần, ngăn chặn triệt để chứng trào ngược, sặc thức ăn và đầy bụng chướng hơi ở cún cưng.', N'Nhựa thực phẩm PP nguyên sinh không chứa BPA, đế cao su chống trượt tuyệt đối.', N'Đổ hạt trải đều vào các khe mê cung. Rửa sạch bằng nước ấm sau mỗi bữa ăn.', 1, 0, '2026-10-11T16:27:00.514854+00:00', '2026-10-11T16:27:00.514854+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'e9b497b7-1054-4da2-92ea-6e60cf8e59d7', N'SUP-BAG-ALL-17', N'Túi Xách Vận Chuyển Thú Cưng Họa Tiết Kẻ Plaid Thoáng Khí', N'plaid-pet-carrier-bag', N'SUPPLY', N'ALL', N'PetTravel', 275000.0, 340000.0, 19, N'Túi (Chịu lực 7kg)', 25, 4.8, 68, N'https://upload.wikimedia.org/wikipedia/commons/4/49/Close-up_of_Plaid_Pet_Carrier_Bag_with_Flower_Charm.jpg', N'TIỆN LỢI', N'Túi xách vải thời trang cao cấp với lưới thoáng khí 4 chiều và khóa an toàn bên trong. Phù hợp cho chó mèo đi khám thú y, đi cà phê hoặc du lịch.', N'Vải Oxford dệt hoa văn bền màu chống thấm nước, lưới nhựa thoáng khí cường lực, khóa kim loại mạ crom.', N'Gài móc xích an toàn vào vòng cổ của bé trước khi kéo khóa túi.', 1, 0, '2026-10-11T16:27:00.514855+00:00', '2026-10-11T16:27:00.514856+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'875bbdd1-58c2-47c6-b43c-fdc64fa96504', N'HYG-LIT-CAT-18', N'Cát Vệ Sinh Cho Mèo Fresh Cat Litter Hút Ẩm Khử Mùi Siêu Vón', N'fresh-cat-litter-clumping', N'HYGIENE', N'CAT', N'Cature Clean', 120000.0, 145000.0, 17, N'Túi 5kg (10L)', 85, 4.9, 260, N'https://upload.wikimedia.org/wikipedia/commons/f/fd/Fresh_cat_litter.JPG', N'BÁN CHẠY', N'Cát khoáng tự nhiên hạt mịn vón nhanh trong 3 giây khi tiếp xúc chất lỏng, khử sạch mùi khai amoniac và hạn chế bụi tối đa bảo vệ đường hô hấp mèo.', N'Bentonite tự nhiên hoạt hóa, hạt carbon hoạt tính khử mùi, hương phấn thơm dịu nhẹ.', N'Rải cát dày 5-7cm vào khay vệ sinh. Dọn bỏ cục vón hàng ngày và châm thêm cát mới.', 1, 1, '2026-10-11T16:27:00.514857+00:00', '2026-10-11T16:27:00.514858+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'ba3ca6e2-72b8-45dc-bec5-e33dfe3dd098', N'HYG-BOX-CAT-19', N'Nhà Vệ Sinh Cho Mèo Modkat Chống Văng Cát Cao Cấp', N'modkat-white-cat-litter-box', N'HYGIENE', N'CAT', N'Modkat Style', 490000.0, 590000.0, 17, N'Bộ kèm xẻng xúc cát', 20, 4.9, 72, N'https://upload.wikimedia.org/wikipedia/commons/4/48/Modkat_Cat_Litter_Box_White_by_Modko.jpg', N'CAO CẤP', N'Khay vệ sinh thiết kế hiện đại kiểu dáng hộp kín chống văng cát ra sàn nhà 99%, nắp trên có lưới gạt chân giữ lại toàn bộ hạt cát rơi rụng.', N'Nhựa ABS đúc nguyên khối chống bám dính vi khuẩn, chịu lực cao cấp.', N'Mở nắp trên để đổ cát. Nhấc nắp lau chùi rửa nước dễ dàng.', 1, 0, '2026-10-11T16:27:00.514859+00:00', '2026-10-11T16:27:00.514860+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'ae3e1293-bbfb-4761-9145-48775b6c79a3', N'HYG-SHP-ALL-20', N'Sữa Tắm Thảo Dược Chiết Xuất Dầu Dừa Dưỡng Mượt Lông Pet Shampoo', N'virgin-coconut-oil-pet-shampoo', N'HYGIENE', N'ALL', N'SOS Herbal', 115000.0, 140000.0, 18, N'Chai 500ml', 60, 4.8, 150, N'https://upload.wikimedia.org/wikipedia/commons/5/58/Pet_shampoo_virgin_coconut_oil_Gliricidia_sepium4.jpg', N'SPA TỰ NHIÊN', N'Sữa tắm hữu cơ chuẩn spa thú y chiết xuất từ tinh dầu dừa nguyên chất và lá thảo mộc. Làm dịu da ngứa, phục hồi lông khô xơ và lưu hương thơm ngọt mát suốt 7 ngày.', N'Tinh dầu dừa Virgin Coconut Oil, chiết xuất Gliricidia sepium, Vitamin E, Protein tơ tằm thủy phân.', N'Pha loãng với nước ấm tỷ lệ 1:4, tạo bọt xoa đều khắp người thú cưng trong 5-10 phút rồi xả sạch.', 1, 0, '2026-10-11T16:27:00.514862+00:00', '2026-10-11T16:27:00.514863+00:00');
INSERT INTO dbo.[products] ([id], [sku], [name], [slug], [category], [target_pet], [brand], [price], [original_price], [discount_percent], [unit], [stock_quantity], [rating], [review_count], [image_url], [badge], [description], [ingredients], [usage_instructions], [is_active], [is_featured], [created_at], [updated_at]) VALUES (N'8861fc7c-2453-4462-b0d4-4e1615051bb3', N'HYG-FLA-ALL-21', N'Dầu Tắm Trị Ve Rận Bọ Chét Chuyên Sâu Shingoli Tick & Flea', N'shingoli-tick-flea-shampoo', N'HYGIENE', N'ALL', N'Shingoli Vet', 135000.0, 160000.0, 15, N'Chai 450ml', 42, 4.9, 88, N'https://upload.wikimedia.org/wikipedia/commons/d/de/Shingoli_shampoo_Tick_n_flea_front.jpg', N'ĐẶC TRỊ VE', N'Công thức dược liệu thú y diệt sạch ve rận, bọ chét và trứng ve bám sâu trên da lông chó mèo ngay trong lần tắm đầu tiên, không gây khô rát hay kích ứng da.', N'Hoạt chất sinh học tự nhiên diệt ngoại ký sinh, chiết xuất sả chanh Melaleuca, chất dưỡng ẩm da.', N'Xoa bọt kỹ vùng cổ, gáy và kẽ móng chân. Giữ bọt 5 phút trước khi xả sạch bằng nước.', 1, 1, '2026-10-11T16:27:00.514866+00:00', '2026-10-11T16:27:00.514866+00:00');
